const ServiceStack: React.FC<ServiceStackProps> = ({
  backgroundColor = "#0B1B3D",
  transparentBackground = false,
  durationInSeconds = 8,
  roofText = "ONE ROOF",
  roofTextColor = "#0B1B3D",
  roofBgColor = "#F4F4F4",
  windowColor = "#0B1B3D",
  services = [
    { label: "Paid media", color: "#2E86DE", icon: "megaphone" },
    { label: "Investor nurturing", color: "#10AC84", icon: "people" },
    { label: "Transaction technology", color: "#9c88ff", icon: "laptop" },
    { label: "Fund administration", color: "#FF9F43", icon: "folder" },
    { label: "Licensed broker-dealer", color: "#1DD1A1", icon: "shield" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Dimensions (Base Units)
  const baseBlockWidth = 840;
  const blockHeight = 100;
  const blockGap = 4;
  const roofHeight = 240;
  const roofOverhang = 40;

  const rw = baseBlockWidth + roofOverhang * 2;
  const rh = roofHeight;

  // Calculate total cluster dimensions to perfectly center it
  const totalStackHeight =
    services.length * blockHeight + Math.max(0, services.length - 1) * blockGap;
  const totalHouseHeight = roofHeight + totalStackHeight;

  // The origin (0,0) of our internal coordinate system will be the top-left of the top block
  const originX = (width - baseBlockWidth * s) / 2;
  const originY = (height - totalHouseHeight * s) / 2 + roofHeight * s;

  // Animation Timing
  const blockStaggerFrames = 8;
  const initialDelay = 15;
  const roofDelay = initialDelay + services.length * blockStaggerFrames + 10;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          top: originY,
          left: originX,
          width: baseBlockWidth * s,
          height: totalStackHeight * s,
        }}
      >
        {/* Render Services from Bottom to Top to build the stack */}
        {services.map((service, idx) => {
          // idx 0 is top, idx length-1 is bottom
          const reverseIdx = services.length - 1 - idx;
          const startFrame = initialDelay + reverseIdx * blockStaggerFrames;

          const progress = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, mass: 0.8, stiffness: 100 },
          });

          // Slide in alternately from left/right
          const slideDirection = reverseIdx % 2 === 0 ? -1 : 1;
          const startOffset = slideDirection * 150 * s;

          const translateX = interpolate(progress, [0, 1], [startOffset, 0]);
          const opacity = interpolate(progress, [0, 0.5], [0, 1], {
            extrapolateRight: "clamp",
          });

          const yPos = idx * (blockHeight + blockGap) * s;

          return (
            <div
              key={`service-${idx}`}
              style={{
                position: "absolute",
                top: yPos,
                left: 0,
                width: baseBlockWidth * s,
                height: blockHeight * s,
                backgroundColor: service.color,
                display: "flex",
                alignItems: "center",
                paddingLeft: 60 * s,
                paddingRight: 40 * s,
                opacity,
                transform: `translateX(${translateX}px)`,
                transition: "none",
                willChange: "transform, opacity",
              }}
            >
              <div style={{ color: "white", marginRight: 30 * s }}>
                <IconSvg type={service.icon} size={48 * s} />
              </div>
              <div
                style={{
                  color: "white",
                  fontSize: 36 * s,
                  fontWeight: 700,
                  fontFamily: interFamily,
                  letterSpacing: "-0.01em",
                }}
              >
                {service.label}
              </div>
            </div>
          );
        })}

        {/* Roof rendering - drops down last */}
        {(() => {
          const roofProgress = spring({
            frame: frame - roofDelay,
            fps,
            config: { damping: 12, mass: 1, stiffness: 90 },
          });

          const roofTranslateY = interpolate(
            roofProgress,
            [0, 1],
            [-200 * s, 0]
          );
          const roofOpacity = interpolate(roofProgress, [0, 0.4], [0, 1], {
            extrapolateRight: "clamp",
          });

          return (
            <div
              style={{
                position: "absolute",
                top: -roofHeight * s,
                left: -roofOverhang * s,
                width: rw * s,
                height: rh * s,
                opacity: roofOpacity,
                transform: `translateY(${roofTranslateY}px)`,
                transition: "none",
                willChange: "transform, opacity",
                zIndex: 10,
              }}
            >
              <svg width="100%" height="100%" viewBox={`0 0 ${rw} ${rh}`}>
                {/* Roof Base Shape */}
                <path
                  d={`M 0,${rh} L 0,${rh - 15} L ${rw / 2},0 L ${rw},${
                    rh - 15
                  } L ${rw},${rh} Z`}
                  fill={roofBgColor}
                  style={{ transition: "none" }}
                />

                {/* 4-Square Window */}
                <g transform={`translate(${rw / 2 - 22}, 36)`}>
                  <rect x="0" y="0" width="20" height="20" fill={windowColor} />
                  <rect x="24" y="0" width="20" height="20" fill={windowColor} />
                  <rect x="0" y="24" width="20" height="20" fill={windowColor} />
                  <rect x="24" y="24" width="20" height="20" fill={windowColor} />
                </g>

                {/* Roof Text */}
                <text
                  x={rw / 2}
                  y={176}
                  textAnchor="middle"
                  fill={roofTextColor}
                  fontFamily={montserratFamily}
                  fontWeight="800"
                  fontSize="72"
                  letterSpacing="0.04em"
                  style={{ transition: "none" }}
                >
                  {roofText}
                </text>
              </svg>
            </div>
          );
        })()}
      </div>
    </AbsoluteFill>
  );
};

export default ServiceStack;